UIScrollerArrowImage=function(game,direction,scrollFunction,releaseFunction,context){Phaser.Image.call(this,game,0,0,direction+'arrow');this.anchor.setTo(0.5,0.5);this.scrollFunction=scrollFunction;this.releaseFunction=releaseFunction;this.context=context;this.pressed=false;this.timePressed=0;this.clicked=false;this.removeTween=null;this.inputEnabled=true;this.input.useHandCursor=true;this.events.onInputDown.add(this._onInputDownHandler,this);this.events.onInputUp.add(this._onInputUpHandler,this);this.events.onInputOver.add(this._onInputOverHandler,this);this.events.onInputOut.add(this._onInputOutHandler,this);this.kill();this.scale.set(0.0,0.0);}
UIScrollerArrowImage.prototype=Object.create(Phaser.Image.prototype);UIScrollerArrowImage.prototype.constructor=UIScrollerArrowImage;UIScrollerArrowImage.prototype.update=function(){if(!this.exists){return;}if(this.pressed||this.clicked){this.scrollFunction.call(this.context);}}
UIScrollerArrowImage.prototype.spawn=function(x,y){this.reset(x,y);this.pressed=false;this.timePressed=0;this.clicked=false;var self=this;if(this.removeTween){this.removeTween.stop();}this.game.add.tween(this.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);}
UIScrollerArrowImage.prototype.releaseClick=function(){if(this.clicked){this.releaseFunction.call(this.context);}this.clicked=false;}
UIScrollerArrowImage.prototype._onInputDownHandler=function(sprite,pointer){this.pressed=true;this.timePressed=pointer.timeDown;this.clicked=false;}
UIScrollerArrowImage.prototype._onInputUpHandler=function(sprite,pointer){if(pointer.timeUp-this.timePressed<UIConstants.MAX_CLICK_LENGTH){this.clicked=true;}else if(this.pressed){this.releaseFunction.call(this.context);}this.pressed=false;}
UIScrollerArrowImage.prototype._onInputOverHandler=function(sprite,pointer){this.game.add.tween(this.scale).to({x:1.2,y:1.2},UIConstants.ELEMENT_SELECTION_TIME,Phaser.Easing.Back.Out,true);}
UIScrollerArrowImage.prototype._onInputOutHandler=function(sprite,pointer){this.game.add.tween(this.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_DESELECTION_TIME,Phaser.Easing.Back.Out,true);}
UIScrollerArrowImage.prototype.remove=function(){this.removeTween=this.game.add.tween(this.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);this.removeTween.onComplete.add(function(){this.kill();},this);}
UIScrollerArrowImage.prototype.retire=function(){this.events.onDragStart.remove(this._onDragStartHandler,this);this.events.onDragStop.remove(this._onDragStopHandler,this);this.kill();}